        c.strokeStyle = rgba(s.n === 'Resolve' ? gold : acc, (.4 + s.f * .5) * th.a); c.lineWidth = 1;
        c.beginPath();
        cn.forEach(([dx, dz]) => { const a = pr(s.x + dx, by, s.z + dz), b = pr(s.x + dx, by - s.h - lift, s.z + dz); c.moveTo(a.x, a.y); c.lineTo(b.x, b.y); });
        cn.forEach(([dx, dz], i) => { const p = pr(s.x + dx, by - s.h - lift, s.z + dz); i ? c.lineTo(p.x, p.y) : c.moveTo(p.x, p.y); });
        const p0 = pr(s.x + cn[0][0], by - s.h - lift, s.z + cn[0][1]); c.lineTo(p0.x, p0.y);
        c.stroke();
        s.top = pr(s.x, by - s.h - lift, s.z);
