            if (s.x === pt[0] && s.z === pt[1]) {
              s.f = 1; const res = si === 3 && !q.resolved; if (res) q.resolved = true;
              this.ring(s.x, this.floorY(s.x, s.z), s.z, res ? gold : acc, res ? 1.4 : .8);
            }
